{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not segments:
        raise ValueError("No segments")
    sum_min = 0
    sum_cap = 0
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError("Missing fields in segment")
        if s['minimum'] < 0 or s['capacity'] < s['minimum']:
            raise ValueError("Invalid min or cap")
        sum_min += s['minimum']
        sum_cap += s['capacity']
    if budget < sum_min or budget > sum_cap:
        raise ValueError("Budget out of range")
    n = len(segments)
    alloc = [s['minimum'] for s in segments]
    current = sum_min
    while current < budget:
        best_idx = -1
        best_priority = -1.0
        for i, s in enumerate(segments):
            if alloc[i] < s['capacity']:
                priority = s['importance'] / (alloc[i] + 1.0)
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            raise ValueError("No capacity to allocate remaining budget")
        alloc[best_idx] += 1
        current += 1
    allocations = alloc
    by_name = {}
    for s, a in zip(segments, alloc):
        by_name[s['name']] = a
    total = budget
    return {"allocations": allocations, "by_name": by_name, "total": total}"}
